import{z as i,x as B,o as E,c as d,q as A,j as n,D as e,d as r,s as o,S as l,b as s}from"./chunks/framework.C8m1ZpeB.js";const H=JSON.parse('{"title":"SHA-3 海绵","description":"","frontmatter":{"title":"SHA-3 海绵","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sha3-sponge.md","filePath":"cs/sha3-sponge.md","lastUpdated":1791413859000}'),p={name:"cs/sha3-sponge.md"};function c(h,a,S,D,m,f){const t=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=A('<h1 id="sha-3-海绵" tabindex="-1">SHA-3 海绵 <a class="header-anchor" href="#sha-3-海绵" aria-label="Permalink to &quot;SHA-3 海绵&quot;">​</a></h1><div class="epigraph"><p>海绵把一个宽置换反复用：先吸收消息进状态，再挤出摘要。输出不必等于整个内部状态，长度扩展那类 MD 遗产从结构上被拆掉。</p><footer>—— Bertoni, Daemen, Peeters and Van Assche, Cryptographic sponge functions；NIST FIPS 202</footer></div><p>上一课<a href="/cs/merkle-damgard">Merkle–Damgård</a>的链接值即摘要前缀。缺口是<strong>另一族</strong>：Keccak 海绵，SHA-3 与 SHAKE。不重写碰撞三条性质，只换构造。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MD 的最终摘要往往就是链状态（或截断但仍泄漏可继续的状态）。海绵：状态分比率 \\(r\\) 与容量 \\(c\\)，吸收阶段把消息块异或进 \\(r\\)，再做置换 \\(f\\)；挤出阶段读 \\(r\\)。容量不直接输出，长度扩展不再「接着压一块」。缺口是海绵的吸收/挤出，不是再背 SHA-256 圈数。</p><h3 id="shake-是-xof" tabindex="-1">SHAKE 是 XOF <a class="header-anchor" href="#shake-是-xof" aria-label="Permalink to &quot;SHAKE 是 XOF&quot;">​</a></h3><p>挤出可任意长，当 PRG 式派生时要换域分离，避免与哈希同一上下文。</p><p><span class="marginnote">FIPS 202。Keccak 置换是 1600 比特。本课不把 SHA-3 写成「SHA-2 被破所以必须换」——SHA-2 仍广泛安全；SHA-3 是结构多样性。</span></p><p><span class="marginnote">数字实例：Keccak-f[1600] 的状态共 1600 比特。SHA3-256 取比率 \\(r=1088\\)、容量 \\(c=512\\)——输出 256 比特时抗碰撞强度是 \\(2^{128}\\) 次操作，因为碰撞必须同时打穿容量；想要更强的 SHAKE128/256，只是换一对 \\(r/c\\) 切分，置换本身不变。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画吸收循环与挤出循环。对比 MD 的单向链。指出 SHAKE128/256 的可变输出。HMAC 对 SHA-3 仍可用，但海绵有 KMAC 更贴结构。</p>',12)),(E(),n(l,null,{default:e(()=>[o(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%B6%88%E6%81%AF%E5%9D%97%22%5D%20--%3E%20ABS%5B%22%E5%90%B8%E6%94%B6%3A%20%E2%8A%95%E8%BF%9B%E6%AF%94%E7%8E%87%E5%86%8D%E7%BD%AE%E6%8D%A2%22%5D%0A%20%20ABS%20--%3E%20ABS%0A%20%20ABS%20--%3E%20SQ%5B%22%E6%8C%A4%E5%87%BA%3A%20%E8%AF%BB%E6%AF%94%E7%8E%87%E5%86%8D%E7%BD%AE%E6%8D%A2%22%5D%0A%20%20SQ%20--%3E%20DIG%5B%22%E6%91%98%E8%A6%81%E6%88%96%20XOF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[r("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"容量 \\(c\\) 对应安全边际：内部有不输出的部分。这服务抗碰撞与原像，前提是 \\(f\\) 像随机置换。它不自动给 MAC；密钥如何拌进海绵，是域分离问题，下一课与 HMAC 一起收。",-1)),(E(),n(l,null,{default:e(()=>[o(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20MD%5B%22Merkle-Damgard%20%E9%93%BE%22%5D%0A%20%20%20%20A%5B%22%E5%9D%971%22%5D%20--%3E%20B%5B%22%E9%93%BE%E5%80%BC%E7%9B%B4%E6%8E%A5%E5%BD%93%E6%91%98%E8%A6%81%E5%89%8D%E7%BC%80%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E6%8B%BF%E5%88%B0%20h%20%E5%8F%AF%E7%BB%AD%E5%86%99%E6%96%B0%E5%9D%97%22%5D%0A%20%20end%0A%20%20subgraph%20SP%5B%22%E6%B5%B7%E7%BB%B5%E6%9E%84%E9%80%A0%22%5D%0A%20%20%20%20D%5B%22%E5%9D%97%E5%BC%82%E6%88%96%E8%BF%9B%E6%AF%94%E7%8E%87%20r%22%5D%20--%3E%20E%5B%22%E5%AE%B9%E9%87%8F%20c%20%E4%BB%8E%E4%B8%8D%E8%BE%93%E5%87%BA%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E5%8F%AA%E8%AF%BB%20r%20%E6%8C%A4%E5%87%BA%2C%20%E5%AE%8C%E6%95%B4%E7%8A%B6%E6%80%81%E4%B8%8D%E5%8F%AF%E5%BE%97%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">直觉类比：容量 \\(c\\) 像沉在水下的底仓——装卸货（消息进出）都只发生在水面（比率 \\(r\\)），旁观者永远看不到底舱里装了什么。攻击者拿不到完整内部状态，「接着压一块」的长扩展戏法就没了舞台。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Keccak 圈函数的 θρπχι 全套。长度扩展与 HMAC 下一课专门关 MD 遗产，并说明为何「\\(H(k\\|m)\\)」不够。</p><p><span class="marginnote">常见误区：初学者容易以为 SHA-3 安全是因为它的圈函数更复杂；其实起决定作用的是构造层面的隔离——容量部分从不输出。圈函数 \\(f\\) 再花哨，若把整个状态亮出来，长度扩展照样成立。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MD 链状态等于可续写的内部。</li><li>海绵：吸收/挤出，容量不直接输出。</li><li>SHA-3 与 SHAKE 是 FIPS 202；与 SHA-2 并存。</li><li>下一课：长度扩展为何逼出 HMAC。</li><li>出处：Bertoni et al., sponge；NIST FIPS 202。</li></ul>',6))])}const _=i(p,[["render",c]]);export{H as __pageData,_ as default};
